// @uniform float SATURATION 1.12 0.0 2.0 "Saturation"                                                                                                                                                                                                                                             
   // @uniform float WARMTH 0.02 -0.2 0.2 "Warmth"                                                                                                                                                                                                                                                    
   // @uniform float WB_STRENGTH 0.3 0.0 1.0 "White Balance"                                                                                                                                                                                                                                          
   // @uniform float STRENGTH 1.0 0.0 1.0 "Strength"                                                                                                                                                                                                                                                  

   void main() {                                                                                                                                                                                                                                                                                      
       vec3 orig = texture(u_video, v_uv).rgb;                                                                                                                                                                                                                                                        
       vec3 c = orig;                                                                                                                                                                                                                                                                                 

       // Smoothed auto contrast (reduced range, gentler response)                                                                                                                                                                                                                                    
       float contrastAdj = mix(1.04, 0.98, u_avg_lum);                                                                                                                                                                                                                                                
       float brightnessAdj = mix(0.008, -0.008, u_avg_lum);                                                                                                                                                                                                                                           
       c = (c - 0.5) * contrastAdj + 0.5 + brightnessAdj;                                                                                                                                                                                                                                             

       // Smoothed auto white balance (narrower gains, lower strength)                                                                                                                                                                                                                                
       float avgTotal = (u_avg_r + u_avg_g + u_avg_b) / 3.0;                                                                                                                                                                                                                                          
       vec3 wbGain = vec3(                                                                                                                                                                                                                                                                            
           mix(1.0, avgTotal / max(u_avg_r, 0.01), WB_STRENGTH * 0.5),                                                                                                                                                                                                                                
           mix(1.0, avgTotal / max(u_avg_g, 0.01), WB_STRENGTH * 0.5),                                                                                                                                                                                                                                
           mix(1.0, avgTotal / max(u_avg_b, 0.01), WB_STRENGTH * 0.5)                                                                                                                                                                                                                                 
       );                                                                                                                                                                                                                                                                                             
       wbGain = clamp(wbGain, 0.90, 1.10);                                                                                                                                                                                                                                                            
       c *= wbGain;                                                                                                                                                                                                                                                                                   

       // Saturation                                                                                                                                                                                                                                                                                  
       float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));                                                                                                                                                                                                                                              
       c = mix(vec3(lum), c, SATURATION);                                                                                                                                                                                                                                                             

       // Warmth                                                                                                                                                                                                                                                                                      
       c.r += WARMTH;                                                                                                                                                                                                                                                                                 
       c.b -= WARMTH;                                                                                                                                                                                                                                                                                 

       fragColor = vec4(clamp(mix(orig, c, STRENGTH), 0.0, 1.0), 1.0);                                                                                                                                                                                                                                
   }

// @uniform float SHARPNESS 1.5 0.0 5.0 "Sharpness"
// @uniform float RADIUS 1.0 0.0 5.0 "Radius"
// @uniform float STRENGTH 1.0 0.0 1.0 "Strength"

void main() {
    // Texel-Größe automatisch berechnen
    vec2 ts = vec2(dFdx(v_uv.x), dFdy(v_uv.y));
    vec3 c = texture(u_video, v_uv).rgb;

    // 3x3 Gaussian Blur berechnen
    vec3 blur = vec3(0.0);
    float count = 0.0;

    for(int y = -1; y <= 1; y++) {
        for(int x = -1; x <= 1; x++) {
            vec2 offset = vec2(float(x), float(y)) * ts * RADIUS;
            blur += texture(u_video, v_uv + offset).rgb;
            count++;
        }
    }
    blur /= count;

    // Unsharp Mask: Original + (Original - Blur) * Stärke
    vec3 res = c + (c - blur) * SHARPNESS;

    // Mit Original mischen basierend auf STRENGTH
    fragColor = vec4(clamp(mix(c, res, STRENGTH), 0.0, 1.0), 1.0);
}

// @uniform float SIGMA_S 1.2 0.1 3.0 "Spatial Radius"
// @uniform float SIGMA_R 0.12 0.01 0.5 "Color Tolerance"
// @uniform float SHARPEN 0.8 0.0 2.0 "Sharpening"

void main() {
    vec2 px = 1.0 / u_res;
    vec3 c = texture(u_video, v_uv).rgb;

    vec3 sum = vec3(0.0);
    float wSum = 0.0;
    for (int dx = -1; dx <= 1; dx++) {
        for (int dy = -1; dy <= 1; dy++) {
            vec3 n = texture(u_video, v_uv + vec2(float(dx), float(dy)) * px).rgb;
            float sw = exp(-float(dx*dx + dy*dy) / (2.0 * SIGMA_S * SIGMA_S));
            float cd = length(n - c);
            float cw = exp(-(cd * cd) / (2.0 * SIGMA_R * SIGMA_R));
            sum  += n * sw * cw;
            wSum += sw * cw;
        }
    }
    vec3 denoised = sum / wSum;

    vec3 nn = texture(u_video, v_uv + vec2( 0,-1) * px).rgb;
    vec3 ss = texture(u_video, v_uv + vec2( 0, 1) * px).rgb;
    vec3 ee = texture(u_video, v_uv + vec2( 1, 0) * px).rgb;
    vec3 ww = texture(u_video, v_uv + vec2(-1, 0) * px).rgb;

    vec3 minRGB = min(denoised, min(min(nn, ss), min(ee, ww)));
    vec3 maxRGB = max(denoised, max(max(nn, ss), max(ee, ww)));
    vec3 rcp    = -1.0 / (sqrt(minRGB / (maxRGB + 1e-4)) + 1.0);
    vec3 amp    = clamp(min(minRGB, 2.0 - maxRGB) * rcp, -0.125, 0.0) * SHARPEN;
    float rcpW  = 1.0 / (1.0 + 4.0 * amp.x);

    fragColor = vec4(clamp((denoised + (nn + ss + ee + ww) * amp) * rcpW, 0.0, 1.0), 1.0);
}
